'use strict';

// MODULES //

var tape = require( 'tape' );
var unset = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof unset, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function throws an error if provided an empty tokens array (cannot unset root)', function test( t ) {
	var doc;

	doc = {
		'a': 1
	};
	t.throws( badValue, Error, 'throws an error when provided empty tokens' );
	t.end();

	function badValue() {
		unset( doc, [] );
	}
});

tape( 'the function immutably removes a value at a shallow path', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = {
		'a': 1,
		'b': 2
	};
	expected = {
		'b': 2
	};

	out = unset( doc, [ 'a' ] );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );

	t.end();
});

tape( 'the function immutably removes a value at a deep path', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = {
		'a': {
			'b': {
				'c': 1,
				'd': 2
			}
		}
	};
	expected = {
		'a': {
			'b': {
				'd': 2
			}
		}
	};

	out = unset( doc, [ 'a', 'b', 'c' ] );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );
	t.notEqual( out.a, doc.a, 'returns expected value' );
	t.notEqual( out.a.b, doc.a.b, 'returns expected value' );

	t.end();
});

tape( 'the function uses structural sharing for unchanged subtrees', function test( t ) {
	var doc;
	var out;

	doc = {
		'a': {
			'b': {
				'c': 1
			}
		},
		'd': {
			'e': 2
		}
	};
	out = unset( doc, [ 'a', 'b', 'c' ] );

	t.strictEqual( out.d, doc.d, 'returns expected value' );
	t.notEqual( out.a, doc.a, 'returns expected value' );

	t.end();
});

tape( 'the function removes an element from an array', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = [ 1, 2, 3 ];
	expected = [ 1, 3 ];

	out = unset( doc, [ '1' ] );
	t.deepEqual( out, expected, 'returns expected value' );
	t.notEqual( out, doc, 'returns expected value' );

	t.end();
});

tape( 'the function removes elements in nested arrays and objects', function test( t ) {
	var expected;
	var doc;
	var out;

	doc = {
		'a': [{
			'b': 1
		}, {
			'b': 2
		}]
	};
	expected = {
		'a': [{
			'b': 2
		}]
	};

	out = unset( doc, [ 'a', '0' ] );
	t.deepEqual( out, expected, 'returns expected value' );
	t.strictEqual( out.a[ 0 ], doc.a[ 1 ], 'returns expected value' );
	t.notEqual( out.a, doc.a, 'returns expected value' );

	t.end();
});

tape( 'the function throws an error if a token is an unsafe value (prototype pollution vector)', function test( t ) {
	var values;
	var i;

	values = [
		'__proto__',
		'constructor',
		'prototype'
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			unset( {}, [ value ] );
		};
	}
});

tape( 'the function throws an error if an intermediate token is an unsafe value', function test( t ) {
	var values;
	var i;

	values = [
		'__proto__',
		'constructor',
		'prototype'
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), Error, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			unset({
				'a': {
					'b': 1
				}
			}, [ value, 'b' ] );
		};
	}
});

tape( 'the function throws a type error if an intermediate path segment references a non-traversable value', function test( t ) {
	var values;
	var i;

	values = [
		'',
		42,
		true,
		null
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws when provided ' + ( typeof values[ i ] ) );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			unset({
				'a': value
			}, [ 'a', 'b' ] );
		};
	}
});

tape( 'the function does not mutate the original document', function test( t ) {
	var doc;
	var out;

	doc = {
		'a': {
			'b': 1,
			'c': 2
		}
	};
	out = unset( doc, [ 'a', 'b' ] );

	t.strictEqual( doc.a.b, 1, 'returns expected value' );
	t.strictEqual( out.a.b, void 0, 'returns expected value' );
	t.strictEqual( out.a.c, 2, 'returns expected value' );

	t.end();
});
